wb = openpyxl.Workbook()
ws = wb.active
ws.title = "TikTok Accounts"

headers = ["STT", "ID (Username)", "Mật khẩu", "Email", "Pass Email", "Webmail Đọc Code", "Cookie / Session Token", "Trạng thái"]
ws.append(headers)

# Styling
header_fill = PatternFill(start_color="1F4E78", end_color="1F4E78", fill_type="solid")
header_font = Font(name="Calibri", size=11, bold=True, color="FFFFFF")
thin_border = Border(
    left=Side(style='thin', color='D9D9D9'),
    right=Side(style='thin', color='D9D9D9'),
    top=Side(style='thin', color='D9D9D9'),
    bottom=Side(style='thin', color='D9D9D9')
)

for col_num in range(1, len(headers) + 1):
    cell = ws.cell(row=1, column=col_num)
    cell.fill = header_fill
    cell.font = header_font
    cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

rows = [r.strip() for r in RAW_DATA.strip().splitlines() if r.strip()]
for idx, r in enumerate(rows, 1):
    parts = r.split('|')
    uid = parts[0] if len(parts) > 0 else ""
    pwd = parts[1] if len(parts) > 1 else ""
    email = parts[2] if len(parts) > 2 else ""
    pmail = parts[3] if len(parts) > 3 else ""
    cookie = parts[4] if len(parts) > 4 else ""
    
    # Determine webmail host
    domain = email.split('@')[-1] if '@' in email else "megacloudx.com"
    webmail_link = f"https://{domain}" if domain else "https://megacloudx.com"
    
    row_data = [idx, uid, pwd, email, pmail, webmail_link, cookie, "Mới mua - Đang test"]
    ws.append(row_data)
    
    for c_idx in range(1, len(row_data) + 1):
        c = ws.cell(row=idx+1, column=c_idx)
        c.border = thin_border
        c.font = Font(name="Calibri", size=10)
        if c_idx == 1:
            c.alignment = Alignment(horizontal="center", vertical="center")
        elif c_idx in [2, 3, 4, 5, 6, 8]:
            c.alignment = Alignment(horizontal="left", vertical="center")
        else:
            c.alignment = Alignment(horizontal="left", vertical="center", wrap_text=False)

# Auto adjust column widths
dims = {1: 8, 2: 24, 3: 20, 4: 35, 5: 16, 6: 28, 7: 45, 8: 20}
for col_idx, width in dims.items():
    ws.column_dimensions[openpyxl.utils.get_column_letter(col_idx)].width = width

out_path = r"d:\TOOL TIKTOK\danh_sach_nick_tiktok.xlsx"
wb.save(out_path)
print(f"Lưu thành công {len(rows)} tài khoản vào file: {out_path}")
